using Metrics;

for (int round = 0; round < 5; round++)
{
    long got = HitCounter.Count(4, 500_000);
    if (got != 2_000_000)
    {
        Console.Error.WriteLine($"round {round}: Count(4, 500000) = {got}, want 2000000 (lost updates)");
        Environment.Exit(1);
    }
}

if (HitCounter.Count(1, 3) != 3 || HitCounter.Count(3, 0) != 0)
{
    Console.Error.WriteLine("small-input behavior wrong");
    Environment.Exit(1);
}

Console.WriteLine("PASS");

