namespace Metrics;

public static class HitCounter
{
    /// <summary>
    /// Count `perWorker` hits from `workers` parallel workers.
    /// Must return exactly workers * perWorker.
    /// </summary>
    public static long Count(int workers, int perWorker)
    {
        long total = 0;
        Parallel.For(0, workers, _ =>
        {
            for (int i = 0; i < perWorker; i++)
            {
                Interlocked.Increment(ref total);
            }
        });
        return total;
    }
}

